"use client";

import React, { useState } from "react";
import { Check, Copy, ChevronDown, ChevronRight, Brain } from "lucide-react";

interface MarkdownRendererProps {
  content: string;
}

export function MarkdownRenderer({ content }: MarkdownRendererProps) {
  // 1. Separate <think> or <thought> reasoning tokens if generated by deep reasoning models
  let thinkingContent: string | null = null;
  let mainContent = content || "";

  const thinkMatch = mainContent.match(/<(?:think|thought)>([\s\S]*?)<\/(?:think|thought)>/i);
  if (thinkMatch) {
    thinkingContent = thinkMatch[1].trim();
    mainContent = mainContent.replace(/<(?:think|thought)>[\s\S]*?<\/(?:think|thought)>/gi, "").trim();
  }

  const [showThinking, setShowThinking] = useState(false);

  return (
    <div className="space-y-3 leading-relaxed text-[var(--text-main)]">
      {/* Collapsible Thinking Process block (like ChatGPT / DeepSeek) */}
      {thinkingContent && (
        <div className="rounded-xl border border-[var(--border-subtle)] bg-[var(--bg-main)]/70 overflow-hidden text-xs my-2">
          <button
            onClick={() => setShowThinking(!showThinking)}
            className="w-full flex items-center justify-between px-3.5 py-2 text-[var(--text-muted)] hover:text-[var(--text-main)] hover:bg-[var(--bg-card)]/50 transition-colors font-medium text-[11px]"
          >
            <div className="flex items-center gap-2">
              <Brain className="w-3.5 h-3.5 text-[#6366F1]" />
              <span>Thought Process</span>
            </div>
            {showThinking ? <ChevronDown className="w-3.5 h-3.5" /> : <ChevronRight className="w-3.5 h-3.5" />}
          </button>
          {showThinking && (
            <div className="p-3.5 pt-1 text-[var(--text-muted)] border-t border-[var(--border-subtle)]/60 whitespace-pre-wrap font-mono text-[11px] leading-relaxed">
              {thinkingContent}
            </div>
          )}
        </div>
      )}

      {/* Main Clean Formatted Text */}
      <FormattedBody content={mainContent} />
    </div>
  );
}

function FormattedBody({ content }: { content: string }) {
  if (!content) return null;

  // Split content by code blocks: ```lang ... ```
  const parts = content.split(/(```[\s\S]*?```)/g);

  return (
    <div className="space-y-3 text-xs leading-relaxed">
      {parts.map((part, index) => {
        if (part.startsWith("```") && part.endsWith("```")) {
          const firstLineEnd = part.indexOf("\n");
          const lang = firstLineEnd > 0 ? part.slice(3, firstLineEnd).trim() || "code" : "code";
          const code = firstLineEnd > 0 ? part.slice(firstLineEnd + 1, -3).trim() : part.slice(3, -3).trim();

          return <CodeBlock key={index} lang={lang} code={code} />;
        }

        return <TextSection key={index} text={part} />;
      })}
    </div>
  );
}

function CodeBlock({ lang, code }: { lang: string; code: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="rounded-xl overflow-hidden border border-[var(--border-subtle)] bg-[var(--bg-main)] my-2 text-xs font-mono shadow-sm">
      <div className="flex items-center justify-between px-3.5 py-1.5 bg-[var(--bg-card)] border-b border-[var(--border-subtle)] text-[var(--text-muted)]">
        <span className="text-[11px] font-semibold text-[var(--text-main)] uppercase">{lang}</span>
        <button
          onClick={handleCopy}
          className="flex items-center gap-1.5 px-2 py-0.5 rounded text-[11px] hover:text-[var(--text-main)] hover:bg-[var(--bg-main)] transition-colors"
        >
          {copied ? <Check className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
          <span>{copied ? "Copied" : "Copy"}</span>
        </button>
      </div>
      <div className="p-3.5 overflow-x-auto text-[var(--text-main)]">
        <pre>{code}</pre>
      </div>
    </div>
  );
}

function TextSection({ text }: { text: string }) {
  // Split into paragraphs by double newlines
  const paragraphs = text.split(/\n\s*\n/);

  return (
    <>
      {paragraphs.map((p, pIdx) => {
        const trimmed = p.trim();
        if (!trimmed) return null;

        const lines = trimmed.split("\n");

        // Check for Headers (#, ##, ###, ####)
        if (trimmed.startsWith("#### ")) {
          return (
            <h5 key={pIdx} className="text-xs font-bold text-[var(--text-main)] mt-3 mb-1">
              {renderInline(trimmed.slice(5))}
            </h5>
          );
        }
        if (trimmed.startsWith("### ")) {
          return (
            <h4 key={pIdx} className="text-sm font-bold text-[var(--text-main)] mt-3 mb-1">
              {renderInline(trimmed.slice(4))}
            </h4>
          );
        }
        if (trimmed.startsWith("## ")) {
          return (
            <h3 key={pIdx} className="text-sm sm:text-base font-bold text-[var(--text-main)] mt-4 mb-1.5">
              {renderInline(trimmed.slice(3))}
            </h3>
          );
        }
        if (trimmed.startsWith("# ")) {
          return (
            <h2 key={pIdx} className="text-base sm:text-lg font-extrabold text-[var(--text-main)] mt-4 mb-2">
              {renderInline(trimmed.slice(2))}
            </h2>
          );
        }

        // Check for Blockquote (> )
        if (trimmed.startsWith("> ")) {
          return (
            <blockquote key={pIdx} className="border-l-2 border-[#6366F1] pl-3 py-1 my-2 text-[var(--text-muted)] italic">
              {renderInline(trimmed.replace(/^>\s*/, ""))}
            </blockquote>
          );
        }

        // Check if all lines are list items (- or * or numbered)
        const isList = lines.length > 0 && lines.every((line) => {
          const l = line.trim();
          return l.startsWith("- ") || l.startsWith("* ") || /^\d+\.\s/.test(l);
        });

        if (isList) {
          const isOrdered = /^\d+\.\s/.test(lines[0].trim());
          if (isOrdered) {
            return (
              <ol key={pIdx} className="space-y-1 pl-4 my-2 list-decimal list-outside marker:text-[#6366F1] marker:font-semibold">
                {lines.map((line, lIdx) => {
                  const content = line.trim().replace(/^\d+\.\s+/, "");
                  return (
                    <li key={lIdx} className="text-[var(--text-main)] pl-1">
                      {renderInline(content)}
                    </li>
                  );
                })}
              </ol>
            );
          } else {
            return (
              <ul key={pIdx} className="space-y-1 pl-4 my-2 list-disc list-outside marker:text-[#6366F1]">
                {lines.map((line, lIdx) => {
                  const content = line.trim().replace(/^[-*]\s+/, "");
                  return (
                    <li key={lIdx} className="text-[var(--text-main)] pl-1">
                      {renderInline(content)}
                    </li>
                  );
                })}
              </ul>
            );
          }
        }

        // Standard natural paragraph (clean text with preserved linebreaks)
        return (
          <p key={pIdx} className="text-[var(--text-main)] leading-relaxed whitespace-pre-wrap">
            {lines.map((line, lIdx) => (
              <React.Fragment key={lIdx}>
                {renderInline(line)}
                {lIdx < lines.length - 1 && <br />}
              </React.Fragment>
            ))}
          </p>
        );
      })}
    </>
  );
}

// Parses inline bold (**text**), italic (*text* or _text_), and inline code (`code`)
function renderInline(text: string): React.ReactNode {
  if (!text) return "";

  // Tokenize code, bold, italic
  const parts = text.split(/(`[^`]+`|\*\*[^*]+\*\*|__[^_]+__|\*[^*]+\*|_[^_]+_)/g);

  return parts.map((part, i) => {
    // Inline code: `code`
    if (part.startsWith("`") && part.endsWith("`") && part.length >= 2) {
      return (
        <code
          key={i}
          className="px-1.5 py-0.5 mx-0.5 rounded bg-[var(--bg-main)] border border-[var(--border-subtle)] font-mono text-[11px] text-[#6366F1]"
        >
          {part.slice(1, -1)}
        </code>
      );
    }
    // Bold: **text** or __text__
    if ((part.startsWith("**") && part.endsWith("**") && part.length >= 4) ||
        (part.startsWith("__") && part.endsWith("__") && part.length >= 4)) {
      return (
        <strong key={i} className="font-semibold text-[var(--text-main)]">
          {part.slice(2, -2)}
        </strong>
      );
    }
    // Italic: *text* or _text_
    if ((part.startsWith("*") && part.endsWith("*") && part.length >= 2) ||
        (part.startsWith("_") && part.endsWith("_") && part.length >= 2)) {
      return (
        <em key={i} className="italic text-[var(--text-main)] opacity-95">
          {part.slice(1, -1)}
        </em>
      );
    }
    return part;
  });
}
